 for(const [x,w,name,sub]of [[35,1120,'REVERSE LOGISTICS','Receive · grade · test · repair · fulfill'],[1200,580,'FORWARD LOGISTICS','Automated receive · ASRS · pack · dispatch']]){ctx.fillStyle=C.floor;round(ctx,x,88,w,845,6);ctx.fill();ctx.strokeStyle='#57707b';ctx.lineWidth=2;ctx.stroke();label(ctx,name,x+15,49,21);label(ctx,sub,x+16,72,12,C.muted);for(let y=100;y<930;y+=30)line(ctx,[[x+5,y],[x+w-5,y]],'#6c87940c',.6);for(let gx=x+15;gx<x+w;gx+=30)line(ctx,[[gx,93],[gx,928]],'#6c87940c',.6);}
