 for(const s of E.stages){const end=s.network==='reverse'?{x:s.port.x,y:s.y<400?365:s.y<650?640:680}:{x:1740,y:s.port.y};conveyor(ctx,E.path([[s.port.x,s.port.y],[end.x,end.y]]),m.t,m.flags.conveyor);}
 E.stages.forEach(s=>drawStage(ctx,s,m,this.selected===s.id,this.depth));
 label(ctx,'YASKAWA INTEGRATION · 14 ARMS',665,426,9,C.orange);m.arms.forEach(a=>{arm(ctx,a,.8);this.hit.push({id:a.id,x:a.x,y:a.y-10,r:15});if(this.selected===a.id){ctx.strokeStyle=C.orange;ctx.lineWidth=2;ctx.strokeRect(a.x-16,a.y-40,32,54);}});
